export default function LoadingScreen() {
  const [isLoading, setIsLoading] = useState(true);
  const [isGlowing, setIsGlowing] = useState(false);

  useEffect(() => {
    // Immediate theme preference check without layout shift
    if (typeof window !== "undefined") {
      const savedTheme = localStorage.getItem("theme");
      if (savedTheme === "light") {
        document.documentElement.setAttribute("data-theme", "light");
      }
    }

    // Lock scroll during splash
    if (typeof document !== "undefined") {
      document.body.style.overflow = "hidden";
    }

    // High performance splash screen timeline:
    // 0ms - 800ms: Smooth, rapid line art drawing (GPU compositor)
    // 800ms: Glow activates (drop-shadow & fill bloom)
    // 1300ms: Splash finishes and smoothly fades out (reveal website)
    const glowTimer = setTimeout(() => {
      setIsGlowing(true);
    }, 800);

    const finishTimer = setTimeout(() => {
      setIsLoading(false);
      if (typeof document !== "undefined") {
        document.body.style.overflow = "";
      }
    }, 1350);

    return () => {
      clearTimeout(glowTimer);
      clearTimeout(finishTimer);
      if (typeof document !== "undefined") {
        document.body.style.overflow = "";
      }
    };
  }, []);

  return (
    <AnimatePresence>
      {isLoading && (
        <motion.div
          key="splash-screen"
          initial={{ opacity: 1 }}
          exit={{
            opacity: 0,
            scale: 1.02,
            transition: { duration: 0.3, ease: [0.25, 0.1, 0.25, 1] },
          }}
          className="fixed inset-0 z-[9999] flex flex-col items-center justify-center select-none overflow-hidden"
          style={{
            backgroundColor: "var(--background)",
            color: "var(--foreground)",
            willChange: "opacity, transform",
            transform: "translate3d(0,0,0)",
          }}
        >
          {/* Hardware-Accelerated Ambient Backlight (Lightweight CSS Blur) */}
          <div
            className="absolute inset-0 flex items-center justify-center pointer-events-none"
            style={{ transform: "translate3d(0,0,0)" }}
          >
            <div
              className={`rounded-full transition-all duration-500 ease-out ${
                isGlowing
                  ? "w-[300px] sm:w-[460px] h-[200px] sm:h-[300px] opacity-40 blur-[80px]"
                  : "w-[240px] sm:w-[360px] h-[160px] sm:h-[220px] opacity-20 blur-[60px]"
              }`}
              style={{
                backgroundColor: "var(--primary)",
                willChange: "transform, opacity",
              }}
            />
            <div
              className={`absolute rounded-full transition-all duration-500 ease-out ${
                isGlowing
                  ? "w-[220px] sm:w-[360px] h-[150px] sm:h-[220px] opacity-30 blur-[70px]"
                  : "w-[180px] sm:w-[260px] h-[120px] sm:h-[180px] opacity-10 blur-[50px]"
              }`}
              style={{
                backgroundColor: "var(--accent-blue)",
                willChange: "transform, opacity",
              }}
            />
          </div>

          {/* Minimalist Top Status Header */}
          <div className="absolute top-7 sm:top-10 flex items-center gap-2.5 text-[11px] font-mono tracking-[0.25em] uppercase opacity-60">
            <span
              className="inline-block w-1.5 h-1.5 rounded-full transition-colors duration-300"
              style={{
                backgroundColor: isGlowing ? "var(--accent-blue)" : "var(--primary)",
                boxShadow: isGlowing ? "0 0 8px var(--accent-blue)" : "0 0 6px var(--primary)",
              }}
            />
            <span>{isGlowing ? "SYSTEM ONLINE" : "LOADING SYSTEM"}</span>
          </div>

          {/* Central Logo Canvas */}
          <div className="relative w-[340px] sm:w-[520px] md:w-[600px] max-w-[92vw] aspect-[864/460] flex items-center justify-center">
            <svg
              viewBox="50 250 764 364"
              className="w-full h-full relative z-10"
              style={{
                overflow: "visible",
                transform: "translate3d(0,0,0)",
              }}
            >
              <defs>
                {/* Stroke Gradient */}
                <linearGradient id="logo-stroke" x1="0%" y1="0%" x2="100%" y2="0%">
                  <stop offset="0%" stopColor="var(--primary)" />
                  <stop offset="60%" stopColor="var(--primary)" />
                  <stop offset="100%" stopColor="var(--accent-blue)" />
                </linearGradient>

                {/* Fill Gradient */}
                <linearGradient id="logo-fill" x1="0%" y1="0%" x2="100%" y2="0%">
                  <stop offset="0%" stopColor="var(--primary)" stopOpacity="0.9" />
                  <stop offset="100%" stopColor="var(--accent-blue)" stopOpacity="0.8" />
                </linearGradient>
              </defs>

              {/* Minimal Tech Framing Reticles */}
              <g stroke="var(--border-color)" strokeWidth="1" opacity="0.5">
                <path d="M 60 270 L 60 256 L 74 256" fill="none" />
                <path d="M 804 270 L 804 256 L 790 256" fill="none" />
                <path d="M 60 598 L 60 612 L 74 612" fill="none" />
                <path d="M 804 598 L 804 612 L 790 612" fill="none" />
              </g>

              {/* The 5 Logo Paths Rendered in Ultra-Smooth Vector Line Art */}
              {LOGO_PATHS.map((item) => (
                <motion.path
                  key={item.id}
                  d={item.d}
                  fill={isGlowing ? "url(#logo-fill)" : "transparent"}
                  stroke="url(#logo-stroke)"
                  strokeWidth={isGlowing ? 2.5 : 2}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  style={{
                    filter: isGlowing
                      ? "drop-shadow(0 0 10px var(--primary)) drop-shadow(0 0 20px var(--primary))"
                      : "drop-shadow(0 0 1.5px var(--primary))",
                    transition: "fill 0.4s ease-out, filter 0.4s ease-out, stroke-width 0.4s ease-out",
                    willChange: "stroke-dashoffset, opacity, fill, filter",
                  }}
                  initial={{ pathLength: 0, opacity: 0 }}
                  animate={{
                    pathLength: 1,
                    opacity: 1,
                  }}
                  transition={{
                    pathLength: {
                      duration: item.duration,
                      delay: item.delay,
                      ease: [0.22, 1, 0.36, 1],
                    },
                    opacity: {
                      duration: 0.2,
                      delay: item.delay,
                    },
                  }}
                />
              ))}
            </svg>
          </div>

          {/* Monogram Brand Footer */}
          <div className="relative z-10 flex flex-col items-center mt-3 sm:mt-5">
            <div
              className="text-xs sm:text-sm font-mono font-bold uppercase tracking-[0.4em] transition-all duration-300"
              style={{
                color: isGlowing ? "var(--foreground)" : "var(--foreground-muted)",
                textShadow: isGlowing ? "0 0 12px var(--primary)" : "none",
              }}
            >
              ABDUL MOID
            </div>

            {/* Fast, Hardware-Accelerated Progress Indicator (Zero React State Thrashing) */}
            <div className="relative w-40 sm:w-52 h-[2px] mt-3 rounded-full overflow-hidden bg-[var(--border-color)]">
              <motion.div
                className="h-full rounded-full"
                style={{
                  background: "linear-gradient(90deg, var(--primary), var(--accent-blue))",
                  boxShadow: isGlowing
                    ? "0 0 12px var(--primary)"
                    : "0 0 4px var(--primary)",
                }}
                initial={{ width: "0%" }}
                animate={{ width: "100%" }}
                transition={{ duration: 1.0, ease: [0.22, 1, 0.36, 1] }}
              />
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
